DECLARE @xml AS XML
       ,@org AS SMALLINT = 6 -- Организация: 1 - МФК Саммит, 4 - ЦВ, 5 - ПКО Доброзайм, 6 - МКК ДЗБР
       ,@creditBureau AS NVARCHAR(50) = 'АО «НБКИ»' -- Бюро:
                                                    -- АО «НБКИ»
                                                    -- АО «БКИ «Скоринг Бюро»
                                                    -- АО «ОКБ»    
       ,@dateOfMail AS NVARCHAR(50) = '13.01.2026' -- Дата исходящего письма (сегодняшняя)
       ,@numberMailFromBureau AS NVARCHAR(50) = 'ИСХ///236314' -- Номер письма от бюро 
       ,@dateMailFromBureau AS NVARCHAR(50) = '22.12.2025' -- Дата письма от бюро
       ,@FIO AS NVARCHAR(300) = 'Козык Евгений Евгеньевич' -- ФИО КЛ
       ,@answer AS NVARCHAR(MAX) = 'информация по заявке с УИД: 39d99971-81c4-11db-999a-1d661ca72cfe-d от 17.02.2025 не отображается в бюро' -- Ответ для Бюро
 

--region МФК Саммит
  IF @org = 1 BEGIN
  SET @xml = (
              SELECT 'Акционерное общество микрофинансовая компания "Саммит"' AS 'NameFullO'
                    ,'9714073258' AS 'INNO'
                    ,'771401001' as 'KPPO'
                    ,'1257700155360' as 'OGRNO'
                    ,'123007, город Москва, Хорошёвское ш, д. 35 к. 1' as 'UiAddrO'
                    ,@creditBureau AS 'creditBureau'
                    ,'б/н' AS 'outMailNumber'
                    ,@dateOfMail AS 'dateOfMail'
                    ,@numberMailFromBureau AS 'numberMailFromBureau'
                    ,@dateMailFromBureau as 'dateMailFromBureau'
                    ,@FIO AS 'FIO'
                    ,@answer AS 'answer'
                    ,'А.П. Эркин' AS 'Signer'
                    ,'Представитель по доворенности' AS 'SignerDoljn'
                    ,'' as 'Pechat'
                    ,'' AS 'Podpis'
                    FOR XML PATH('root'),type)



              END        
--endregion 
--region Центр Взыскания
  ELSE IF @org = 4 BEGIN
    SET @xml = (SELECT 'Общество с ограниченной ответственностью "Центр Взыскания"' AS 'NameFullO'
                    ,'7724866608' AS 'INNO'
                    ,'770601001' as 'KPPO'
                    ,'1137746180770' as 'OGRNO'
                    ,'119180, город Москва, Старомонетный пер., д. 14 стр. 2, помещ. 4' as 'UiAddrO'
                    ,@creditBureau AS 'creditBureau'
                    ,'б/н' AS 'outMailNumber'
                    ,@dateOfMail AS 'dateOfMail'
                    ,@numberMailFromBureau AS 'numberMailFromBureau'
                    ,@dateMailFromBureau as 'dateMailFromBureau'
                    ,@FIO AS 'FIO'
                    ,@answer AS 'answer'
                    ,'А.П. Эркин' AS 'Signer'
                    ,'Представитель по доворенности' AS 'SignerDoljn'
                    ,'' AS 'Pechat'
                    ,'' AS 'Podpis'
                    FOR XML PATH('root'),type)
END 
--endregion 
--region ПКО Доброзайм
  ELSE IF @org = 5 BEGIN
  SET @xml = (SELECT 'Общество с ограниченной ответственностью профессиональная коллекторская организация "Доброзайм"' AS 'NameFullO'
                    ,'7717795970' AS 'INNO'
                    ,'770601001' as 'KPPO'
                    ,'5147746190851' as 'OGRNO'
                    ,'119180, г. Москва, пер. Старомонетный, д. 14, стр. 2, пом. 6-2' as 'UiAddrO'
                    ,@creditBureau AS 'creditBureau'
                    ,'б/н' AS 'outMailNumber'
                    ,@dateOfMail AS 'dateOfMail'
                    ,@numberMailFromBureau AS 'numberMailFromBureau'
                    ,@dateMailFromBureau as 'dateMailFromBureau'
                    ,@FIO AS 'FIO'
                    ,@answer AS 'answer'
                    ,'А.П. Эркин' AS 'Signer'
                    ,'Представитель по доворенности' AS 'SignerDoljn'
                    ,'' AS 'Pechat','' AS 'Podpis'
                    FOR XML PATH('root'),type)
END 
--endregion
--region МКК ДЗБР
  ELSE IF @org = 6 BEGIN
  SET @xml = (SELECT 'Общество с ограниченной ответственностью микрокредитная компания «ДоброЗайм Быстрое решение»' AS 'NameFullO'
                    ,'7725850061' AS 'INNO'
                    ,'771401001' as 'KPPO'
                    ,'5147746405637' as 'OGRNO'
                    ,'123007, город Москва, Хорошёвское ш., д. 35 к. 1, помещ. 20а .22' as 'UiAddrO'
                    ,@creditBureau AS 'creditBureau'
                    ,'б/н' AS 'outMailNumber'
                    ,@dateOfMail AS 'dateOfMail'
                    ,@numberMailFromBureau AS 'numberMailFromBureau'
                    ,@dateMailFromBureau as 'dateMailFromBureau'
                    ,@FIO AS 'FIO'
                    ,@answer AS 'answer'
                    ,'А.П. Эркин' AS 'Signer'
                    ,'Представитель по доворенности' AS 'SignerDoljn'
                    ,'' AS 'Pechat','' AS 'Podpis'
                    FOR XML PATH('root'),type)
END 
--endregion

SELECT @xml

